namespace ghidra.app.plugin.core.searchtext;

using ghidra.app.plugin.core.searchtext.Searcher;
using ghidra.app.util;
using ghidra.app.util.query;
using ghidra.framework.options;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util.datastruct;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * Table model for showing the results of a "Search All"
 */
public abstract class AbstractSearchTableModel : ProgramLocationPreviewTableModel {

	static string TITLE = "Text Search";

	protected SearchOptions options;
	protected int searchLimit;
	protected AddressSetView set;
	protected bool showBlockName;

	private PluginTool tool;

	public AbstractSearchTableModel(PluginTool tool, Program p, AddressSetView set,
			SearchOptions options) : base(TITLE, tool, p, null, true)
    {
		this.tool = tool;
		this.set = set;
		this.options = options;
		Options opt = tool.getOptions(SearchConstants.SEARCH_OPTION_NAME);
		searchLimit =
			opt.getInt(SearchConstants.SEARCH_LIMIT_NAME, SearchConstants.DEFAULT_SEARCH_LIMIT);
	}

	/* @Override */
	protected void doLoad(Accumulator<ProgramLocation> accumulator, TaskMonitor monitor)
    {
		Searcher searcher = getSearcher(tool, monitor);
		monitor.checkCancelled();
		TextSearchResult result = searcher.search();
		while (result != null && accumulator.getProgress() < searchLimit) {
			accumulator.add(result.programLocation());
			monitor.checkCancelled();
			result = searcher.search();
		}
	}

	/**
	 * Get the Searcher that does the text search
	 * 
	 * @param pluginTool the tool
	 * @param monitor the monitor
	 * @return the searcher to use for searching
	 */
	protected abstract Searcher getSearcher(PluginTool pluginTool, TaskMonitor monitor);
}
